"""Versioned visual vocabulary used by both indexing and query profiling."""

TAXONOMY_VERSION = "2026-10-20.1"


def _label(identifier: str, label: str, description: str, keywords: str) -> dict:
    return {"id": identifier, "label": label, "description": description, "keywords": keywords.split("|")}


